import { access } from "node:fs/promises";
import { resolve, dirname } from "node:path";
import { createJiti } from "jiti";
import { normalizeBaseUrl, normalizeSiteUrl } from "./site-url.js";
import { doxygen as doxygenSource, godoc as godocSource, markdown as markdownSource, mcp as mcpSource, mkdocs as mkdocsSource, openapi as openapiSource, rustdoc as rustdocSource, } from "./adapters/index.js";
import { DEFAULT_CODE_SAMPLE_LANGS, SUPPORTED_CODE_SAMPLE_LANGS } from "./utils/code-samples.js";
export function defineConfig(config) {
    return config;
}
// ---------------------------------------------------------------------------
// Config loading
// ---------------------------------------------------------------------------
const DEFAULT_COLORS = {
    primary: "99 102 241",
    light: "129 140 248",
    dark: "79 70 229",
};
const DEFAULT_FONT_SANS = "Inter";
const SYSTEM_SANS = "ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif";
const SYSTEM_MONO = "ui-monospace, 'SF Mono', 'Cascadia Code', Consolas, 'Liberation Mono', Menlo, monospace";
const DEFAULT_LAYOUT = {
    sidebar: "18rem",
    toc: "19rem",
    content: "44rem",
};
export async function loadConfig(configOrDir) {
    let configPath;
    if (configOrDir && configOrDir.endsWith(".ts")) {
        configPath = resolve(configOrDir);
    }
    else {
        const dir = configOrDir ?? process.cwd();
        configPath = resolve(dir, "sourcey.config.ts");
    }
    try {
        await access(configPath);
    }
    catch {
        throw new Error(`Config not found: ${configPath}\n` +
            `Create one with:\n\n` +
            `  import { defineConfig } from "sourcey";\n` +
            `  export default defineConfig({ navigation: { tabs: [...] } });\n`);
    }
    const jiti = createJiti(import.meta.url);
    const mod = (await jiti.import(configPath));
    const raw = mod.default;
    if (!raw?.navigation?.tabs) {
        throw new Error("sourcey.config.ts must export default defineConfig({ navigation: { tabs: [...] } })");
    }
    return resolveConfigFromRaw(raw, dirname(configPath));
}
/**
 * Build a ResolvedConfig for a standalone spec file (no config file needed).
 */
export function configFromSpec(specPath) {
    const absSpec = resolve(specPath);
    return {
        name: "API Reference",
        titleSeparator: " - ",
        siteUrl: undefined,
        baseUrl: "",
        prettyUrls: false,
        theme: {
            preset: "default",
            colors: { ...DEFAULT_COLORS },
            fonts: {
                sans: `'${DEFAULT_FONT_SANS}', ${SYSTEM_SANS}`,
                mono: SYSTEM_MONO,
                googleFont: DEFAULT_FONT_SANS,
            },
            layout: { ...DEFAULT_LAYOUT },
            css: [],
        },
        codeSamples: ["curl", "javascript", "python"],
        tabs: [
            {
                label: "API Reference",
                slug: "api",
                source: { kind: "openapi", spec: absSpec, watchPaths: [absSpec] },
                openapi: absSpec,
            },
        ],
        navbar: { links: [] },
        footer: { links: [] },
        changelog: { enabled: true, feed: false, permalinks: false, ogImages: false },
        search: { featured: [] },
    };
}
// ---------------------------------------------------------------------------
// Resolution + validation
// ---------------------------------------------------------------------------
export async function resolveConfigFromRaw(raw, configDir) {
    const theme = resolveTheme(raw, configDir);
    const logo = resolveLogo(raw.logo, configDir);
    const tabs = await resolveTabs(raw.navigation.tabs, configDir);
    const changelog = resolveChangelog(raw.changelog);
    return {
        name: raw.name ?? "",
        titleSeparator: raw.titleSeparator ?? " - ",
        siteUrl: normalizeSiteUrl(raw.siteUrl),
        baseUrl: normalizeBaseUrl(raw.baseUrl),
        prettyUrls: resolvePrettyUrls(raw.prettyUrls),
        theme,
        logo,
        favicon: raw.favicon && !raw.favicon.startsWith("http") && !raw.favicon.startsWith("data:")
            ? resolve(configDir, raw.favicon)
            : raw.favicon,
        ogImage: raw.ogImage && !raw.ogImage.startsWith("http") && !raw.ogImage.startsWith("data:")
            ? resolve(configDir, raw.ogImage)
            : raw.ogImage,
        repo: raw.repo,
        editBranch: raw.editBranch,
        editBasePath: raw.editBasePath,
        codeSamples: resolveCodeSamples(raw.codeSamples),
        tabs,
        navbar: {
            links: raw.navbar?.links ?? [],
            primary: raw.navbar?.primary,
        },
        footer: {
            links: raw.footer?.links ?? [],
        },
        changelog,
        search: {
            featured: raw.search?.featured ?? [],
        },
    };
}
function isUrl(source) {
    return source.startsWith("http://") || source.startsWith("https://");
}
const VALID_PRESETS = ["default", "minimal", "api-first"];
function resolveTheme(raw, configDir) {
    const preset = raw.theme?.preset ?? "default";
    if (!VALID_PRESETS.includes(preset)) {
        throw new Error(`Invalid theme preset "${preset}". Must be one of: ${VALID_PRESETS.join(", ")}`);
    }
    const rawColors = raw.theme?.colors;
    const colors = rawColors
        ? {
            primary: hexToRgb(rawColors.primary),
            light: rawColors.light ? hexToRgb(rawColors.light) : hexToRgb(rawColors.primary),
            dark: rawColors.dark ? hexToRgb(rawColors.dark) : hexToRgb(rawColors.primary),
        }
        : { ...DEFAULT_COLORS };
    const sansName = raw.theme?.fonts?.sans ?? DEFAULT_FONT_SANS;
    const monoName = raw.theme?.fonts?.mono;
    const fonts = {
        sans: `'${sansName}', ${SYSTEM_SANS}`,
        mono: monoName ? `'${monoName}', ${SYSTEM_MONO}` : SYSTEM_MONO,
        googleFont: sansName,
    };
    const layout = {
        sidebar: raw.theme?.layout?.sidebar ?? DEFAULT_LAYOUT.sidebar,
        toc: raw.theme?.layout?.toc ?? DEFAULT_LAYOUT.toc,
        content: raw.theme?.layout?.content ?? DEFAULT_LAYOUT.content,
    };
    const css = (raw.theme?.css ?? []).map((p) => resolve(configDir, p));
    return { preset, colors, fonts, layout, css };
}
function resolveLogo(logo, configDir) {
    if (!logo)
        return undefined;
    const resolvePath = (p) => p && !p.startsWith("http") && !p.startsWith("data:") ? resolve(configDir, p) : p;
    if (typeof logo === "string")
        return { light: resolvePath(logo) };
    return { light: resolvePath(logo.light), dark: resolvePath(logo.dark), href: logo.href };
}
function resolveChangelog(raw) {
    if (raw === false) {
        return { enabled: false, feed: false, permalinks: false, ogImages: false };
    }
    return {
        enabled: raw?.enabled ?? true,
        feed: raw?.feed === true ? {} : (raw?.feed ?? false),
        permalinks: raw?.permalinks ?? false,
        ogImages: raw?.ogImages ?? false,
    };
}
async function resolveTabs(tabs, configDir) {
    const slugs = new Set();
    const resolved = [];
    for (const tab of tabs) {
        if (!tab.tab)
            throw new Error('Tab missing "tab" name');
        const slug = tab.slug !== undefined ? tab.slug : slugify(tab.tab);
        if (slugs.has(slug))
            throw new Error(`Duplicate tab slug "${slug}" (from "${tab.tab}")`);
        slugs.add(slug);
        const sources = [
            tab.source,
            tab.openapi,
            tab.mkdocs,
            tab.groups?.length ? tab.groups : undefined,
            tab.doxygen,
            tab.mcp,
            tab.godoc,
            tab.rustdoc,
        ].filter(Boolean).length;
        if (sources > 1) {
            throw new Error(`Tab "${tab.tab}" has multiple sources; use only one of "source", "openapi", "mkdocs", "groups", "doxygen", "mcp", "godoc", or "rustdoc"`);
        }
        if (sources === 0) {
            throw new Error(`Tab "${tab.tab}" needs one of "source", "openapi", "mkdocs", "groups", "doxygen", "mcp", "godoc", or "rustdoc"`);
        }
        const adapter = tab.source ?? legacySourceAdapter(tab);
        const source = await adapter.resolve({
            configDir,
            tabName: tab.tab,
            tabSlug: slug,
            resolvePath: (path) => resolve(configDir, path),
            assertExists,
            isUrl,
        });
        resolved.push(resolvedTabFromSource(tab.tab, slug, source));
    }
    return resolved;
}
function legacySourceAdapter(tab) {
    if (tab.openapi)
        return openapiSource(tab.openapi);
    if (tab.mkdocs)
        return mkdocsSource(tab.mkdocs);
    if (tab.mcp)
        return mcpSource(tab.mcp);
    if (tab.doxygen)
        return doxygenSource(tab.doxygen);
    if (tab.godoc)
        return godocSource(tab.godoc);
    if (tab.rustdoc)
        return rustdocSource(tab.rustdoc);
    return markdownSource({ groups: tab.groups });
}
function resolvedTabFromSource(label, slug, source) {
    const base = { label, slug, source };
    switch (source.kind) {
        case "openapi":
            return { ...base, openapi: source.spec };
        case "mcp":
            return { ...base, mcp: source.spec };
        case "markdown":
            return {
                ...base,
                mkdocs: source.adapter === "mkdocs" ? source.configPath : undefined,
                groups: source.groups,
            };
        case "doxygen":
            return { ...base, doxygen: source.config };
        case "godoc":
            return { ...base, godoc: source.config };
        case "rustdoc":
            return { ...base, rustdoc: source.config };
    }
}
// ---------------------------------------------------------------------------
// Utilities
// ---------------------------------------------------------------------------
export function slugify(name) {
    return name
        .toLowerCase()
        .replace(/[^a-z0-9]+/g, "-")
        .replace(/^-|-$/g, "");
}
/** Build a path under a tab, handling empty slugs (root-level tabs). */
export function tabPath(tabSlug, file) {
    if (!tabSlug)
        return file;
    if (file.startsWith(`${tabSlug}/`))
        return file;
    return `${tabSlug}/${file}`;
}
/** Build the on-disk output path for a tab landing page. */
export function tabIndexOutputPath(tabSlug, prettyUrls) {
    if (!tabSlug)
        return "index.html";
    if (prettyUrls === "slash")
        return tabPath(tabSlug, "index.html");
    return `${tabSlug}.html`;
}
/**
 * Build the on-disk output path for a content page within a tab.
 * `"slash"` emits directory indexes. `false` and `"strip"` emit `.html`
 * files; `"strip"` only changes the public URL, not the file layout.
 */
export function pageOutputPath(tabSlug, slug, prettyUrls) {
    if (slug === "index") {
        return tabIndexOutputPath(tabSlug, prettyUrls);
    }
    if (prettyUrls === "slash") {
        return tabPath(tabSlug, `${slug}/index.html`);
    }
    return tabPath(tabSlug, `${slug}.html`);
}
function resolvePrettyUrls(value) {
    if (value === undefined || value === false)
        return false;
    if (value === "slash" || value === "strip")
        return value;
    throw new Error(`Invalid prettyUrls "${String(value)}". Expected false, "slash", or "strip".`);
}
export function hexToRgb(hex) {
    const h = hex.replace(/^#/, "");
    if (!/^[0-9a-fA-F]{6}$/.test(h))
        throw new Error(`Invalid hex color: "${hex}"`);
    const r = parseInt(h.slice(0, 2), 16);
    const g = parseInt(h.slice(2, 4), 16);
    const b = parseInt(h.slice(4, 6), 16);
    return `${r} ${g} ${b}`;
}
function resolveCodeSamples(value) {
    const langs = value ?? DEFAULT_CODE_SAMPLE_LANGS;
    const unsupported = langs.filter((lang) => !SUPPORTED_CODE_SAMPLE_LANGS.includes(lang));
    if (unsupported.length) {
        throw new Error(`Invalid codeSamples value "${unsupported[0]}". Must be one of: ${SUPPORTED_CODE_SAMPLE_LANGS.join(", ")}`);
    }
    return [...langs];
}
async function assertExists(filePath, label) {
    try {
        await access(filePath);
    }
    catch {
        throw new Error(`${label} not found: ${filePath}`);
    }
}
